<?php
/** New recovery proof, rebuilt from production contracts; never historical test recovery. */
require __DIR__.'/operations_resume_439_schema.php';
operationsResumeCleanup(['CompanyProjectDiscussionsSchema','CompanyProjectDiscussionExtrasSchema']);
require __DIR__.'/portal_operations_setup.php';
require_once APPPATH.'services/CompanyProjectDiscussions.php';
require_once APPPATH.'services/CompanyProjectDiscussionChanges.php';
require_once APPPATH.'services/CompanyProjectDiscussionFiles.php';
require_once APPPATH.'services/CompanyPortalProjectDiscussions.php';
foreach (['CompanyProjectDiscussionsSchema','CompanyProjectDiscussionExtrasSchema'] as $schema) operationsResumeSchema($db,$p,$schema);
$resumeKey=static fn(string $label):string=>hash('sha256','recovery439-discussion-'.$label);
$resumeDiscussion=new CompanyProjectDiscussions($db,$p,str_repeat('synthetic-',4));
$resumeContactDiscussion=new CompanyPortalProjectDiscussions($db,$p,str_repeat('synthetic-',4));
$resumeChanges=new CompanyProjectDiscussionChanges($db,$p,str_repeat('synthetic-',4));
$resumeFiles=new CompanyProjectDiscussionFiles($db,$p,str_repeat('synthetic-',4));
foreach ([[$a,$ca],[$b,$cb]] as [$owner,$client]) {
    $project=$portalParents['projects'][$owner];
    $access=new CompanyContactOperationAccess($db,$p,'projects');
    $current=$access->page($owner,7,$client)[$contactIds[$owner]];
    $access->set($owner,7,$client,$contactIds[$owner],$current['revision'],'1');
    $parent=$projectWriter->get($owner,7,$project);
    $publication->set($owner,7,'projects',$project,$parent['revision'],'record',null,true,$resumeKey('publish-project-'.$owner));
    $page=$resumeDiscussion->staffPage($owner,7,$project);
    $resumeDiscussion->saveRules($owner,7,$project,$page['project']['revision'],$page['collection_revision'],$page['rules']['revision'],['open_discussions'=>'1'],['project_discussions'=>'1'],$resumeKey('rules-'.$owner));
    $page=$resumeDiscussion->staffPage($owner,7,$project);
    $args=[$owner,7,$project,$page['project']['revision'],$page['collection_revision'],'Private staff thread','Synthetic confidential body',$resumeKey('thread-'.$owner)];
    $opened=$resumeDiscussion->staffOpen(...$args);
    essentialCheck($resumeDiscussion->staffOpen(...$args)===$opened,'staff thread durable retry keeps same identity A/B');
    $thread=(int)$opened['id'];
    $contactPage=$resumeContactDiscussion->page($sessions[$owner],$owner,$project);
    essentialCheck($contactPage!==null&&count($contactPage['items'])===0,'staff discussion remains private by default A/B');
    $page=$resumeDiscussion->staffPage($owner,7,$project,$thread);
    $resumeDiscussion->threadState($owner,7,$project,$page['project']['revision'],$page['collection_revision'],$thread,(int)$page['thread']['revision'],'publish',true,$resumeKey('thread-publish-'.$owner));
    $contactPage=$resumeContactDiscussion->page($sessions[$owner],$owner,$project);
    essentialCheck(count($contactPage['items'])===1,'explicit thread publication enables only own contact A/B');
    $page=$resumeDiscussion->staffPage($owner,7,$project,$thread);
    $postArgs=[$sessions[$owner],$owner,$project,$page['project']['revision'],$page['collection_revision'],$thread,(int)$page['thread']['revision'],'Contact response',$resumeKey('contact-post-'.$owner)];
    $posted=$resumeDiscussion->contactComment(...$postArgs);
    essentialCheck($resumeDiscussion->contactComment(...$postArgs)===$posted,'contact comment retries a single own author receipt A/B');
    $post=(int)$posted['id'];
    $workspace=$resumeChanges->workspace($sessions[$owner],$owner,$project,$thread,$post);
    essentialCheck($workspace['body']==='Contact response'&&$workspace['can_change'],'contact can edit its own explicitly authored comment');
    $changeArgs=[$sessions[$owner],$owner,$project,$workspace['project_revision'],$workspace['collection_revision'],$thread,$workspace['discussion_revision'],$post,$workspace['content_revision'],'edit','Revised own response',$resumeKey('edit-'.$owner)];
    $changed=$resumeChanges->contactChange(...$changeArgs);
    essentialCheck($resumeChanges->contactChange(...$changeArgs)===$changed,'edit retries immutable own-change receipt');
    $workspace=$resumeChanges->workspace($sessions[$owner],$owner,$project,$thread,$post);
    essentialCheck($workspace['body']==='Revised own response'&&$workspace['content_revision']===2,'edit stores another version and advances content revision');
    $uploadArgs=[$sessions[$owner],$owner,$project,$workspace['project_revision'],$workspace['collection_revision'],$thread,$workspace['discussion_revision'],$post,$workspace['content_revision'],$resumeKey('file-'.$owner),'proof.pdf',"%PDF-1.4\nSynthetic recovery proof\n%%EOF\n"];
    $uploaded=$resumeFiles->contactUpload(...$uploadArgs);
    essentialCheck($resumeFiles->contactUpload(...$uploadArgs)===$uploaded,'private own-comment attachment upload is idempotent');
    $files=$resumeFiles->contactList($sessions[$owner],$owner,$project,$thread,$post);
    essentialCheck(count($files['files'])===1,'author sees own private comment attachment');
    $file=$files['files'][0]['file_key'];
    $bytes=$resumeFiles->download($sessions[$owner],$owner,$project,$thread,$post,$file);
    $resumeFiles->confirmDownload($sessions[$owner],$owner,$project,$thread,$post,$bytes);
    essentialCheck($bytes['content']===$uploadArgs[count($uploadArgs)-1],'private attachment bytes are revalidated and returned to exact owner');
    $other=$owner===$a?$b:$a;
    essentialCheck($resumeContactDiscussion->page($sessions[$other],$owner,$project)===null,'foreign contact session cannot hydrate project discussion');
    essentialThrows(fn()=>$resumeDiscussion->staffPage($other,7,$project,$thread),'company_project_discussion_unavailable','staff direct project/thread cross-owner denied');
    essentialThrows(fn()=>$resumeFiles->download($sessions[$other],$owner,$project,$thread,$post,$file),'company_project_discussion_unavailable','foreign session cannot download another company file');
    // A second contact of this same client has independent authorship and cannot use a private file.
    $second=$people->save($owner,7,$client,['firstname'=>'Second','lastname'=>'Contact','email'=>'second-operation@example.invalid']);
    $db->query('UPDATE '.$p.'contacts SET password=? WHERE id=?',[password_hash('synthetic-second-contact',PASSWORD_DEFAULT),$second]);
    $secondAccess=new CompanyContactOperationAccess($db,$p,'projects');
    $secondCurrent=$secondAccess->page($owner,7,$client)[$second];
    $secondAccess->set($owner,7,$client,$second,$secondCurrent['revision'],'1');
    $secondSession=$portal->login($owner,'second-operation@example.invalid','synthetic-second-contact','password_verify');
    essentialCheck(count($resumeContactDiscussion->page($secondSession,$owner,$project)['items'])===1,'same-client contact may see explicitly published thread');
    essentialThrows(fn()=>$resumeFiles->download($secondSession,$owner,$project,$thread,$post,$file),'company_project_discussion_unavailable','same-client contact does not inherit private author attachment');
    // A late failed audit must leave text, collection, versions and receipts unchanged.
    $workspace=$resumeChanges->workspace($sessions[$owner],$owner,$project,$thread,$post);
    $before=[];
    foreach (['company_project_discussions','company_project_discussion_posts','company_discussion_post_heads','company_discussion_post_versions','company_project_discussion_states','company_project_discussion_requests'] as $table) $before[$table]=$db->query('SELECT * FROM '.$p.$table.' WHERE issuer_id=?',[$owner])->result_array();
    $db->failOn='INSERT INTO '.$p.'issuers_audit';
    essentialThrows(fn()=>$resumeChanges->contactChange($sessions[$owner],$owner,$project,$workspace['project_revision'],$workspace['collection_revision'],$thread,$workspace['discussion_revision'],$post,$workspace['content_revision'],'edit','Must rollback',$resumeKey('failed-edit-'.$owner)),'issuer_storage_failed','failed audit rolls back own comment change');
    $db->failOn=null;
    foreach ($before as $table=>$rows) essentialCheck($db->query('SELECT * FROM '.$p.$table.' WHERE issuer_id=?',[$owner])->result_array()===$rows,'failed own edit preserves original '.$table);
    $db->query('DELETE FROM '.$p.'contact_permissions WHERE userid=? AND permission_id=6',[$contactIds[$owner]]);
    essentialCheck($resumeContactDiscussion->page($sessions[$owner],$owner,$project)===null,'project permission revocation hides prior discussion');
    essentialThrows(fn()=>$resumeFiles->download($sessions[$owner],$owner,$project,$thread,$post,$file),'company_project_discussion_unavailable','permission revocation prevents private bytes');
}
// A restricted employee needs both explicit membership and the project capability.
$db->query('INSERT INTO '.$p.'staff(staffid,active,admin) VALUES(39,1,0)');
$db->query('INSERT INTO '.$p.'issuers_staff(issuer_id,staff_id,can_view) VALUES(?,39,1)',[$a]);
essentialThrows(fn()=>$resumeDiscussion->staffPage($a,39,$portalParents['projects'][$a]),'company_project_discussion_access_denied','membership alone does not grant discussion access');
$db->query('INSERT INTO '.$p.'issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(?,39,?,?)',[$a,'projects','view']);
essentialCheck(count($resumeDiscussion->staffPage($a,39,$portalParents['projects'][$a])['items'])===1,'explicit A-only project view authorizes existing own discussion');
essentialThrows(fn()=>$resumeDiscussion->staffPage($b,39,$portalParents['projects'][$b]),'company_project_discussion_access_denied','restricted employee cannot hydrate B discussion');
$db->query('DELETE FROM '.$p.'issuers_resource_permissions WHERE issuer_id=? AND staff_id=39 AND feature=?',[$a,'projects']);
essentialThrows(fn()=>$resumeDiscussion->staffPage($a,39,$portalParents['projects'][$a]),'company_project_discussion_access_denied','revocation blocks prior own-company discussion read');
echo 'Rebuilt recovery439 discussions/own versions/private files/A+B/retry/audit rollback/revocation: '.$GLOBALS['essentialChecks'].' cumulative checks passed ('.$db->driver().').'.PHP_EOL;
